from lib import *
S = SS('s44')
steps = [
    step("DOWNLOAD_HANDLERS_BASE(协议 → 处理器):http、https 是 HTTP11DownloadHandler(Twisted),file 是 FileDownloadHandler,data 是 DataURIDownloadHandler,ftp 是 FTPDownloadHandler,s3 是 S3DownloadHandler。你用 DOWNLOAD_HANDLERS 覆盖或追加;值设成 None 就禁用这个协议。", t=tl(S(1)), mark=lidx(S(1), 'http11', 'datauri'), kv=KV([['http / https', 'HTTP11DownloadHandler(Twisted)'], ['file / data', 'FileDownloadHandler / DataURIDownloadHandler'], ['ftp / s3', 'FTPDownloadHandler / S3DownloadHandler'], ['DOWNLOAD_HANDLERS', '覆盖或追加;None = 禁用']], ['DOWNLOAD_HANDLERS'])),
    step("file:// 和 data: 不经过网络:file://…/hello.html 得到 HtmlResponse(status 200,38 字节,响应头是空的 {}),file://…/blob.bin 得到普通 Response(256 字节,没有 .text),不存在的文件 errback 收到 FileNotFoundError,目录收到 IsADirectoryError;data: 的 base64 + charset=utf-8 的 URI 得到 TextResponse(23 字节,文本“数据 URI 里的中文”),data:,hello%20world 是 TextResponse(11 字节),data:text/html,<h1>x</h1> 是 HtmlResponse(10 字节)。响应类由扩展名或 MIME 决定。", t=tl(S(2)), mark=lidx(S(2), 'missing.html', 's44b  '), done=lidx(S(2), 'hello.html', 'blob.bin', 'hello%20world'), kv=KV([['file://', '响应头为空;类按扩展名;不存在 → FileNotFoundError'], ['data:', '按 MIME 决定响应类,支持 base64 和 charset'], ['目录', 'IsADirectoryError']], ['file://'])),
    step("自定义处理器:写一个继承 BaseDownloadHandler 的类、实现 async download_request(request) 返回 Response,用 DOWNLOAD_HANDLERS = {'myproto': MyHandler} 注册——myproto://some/resource 的请求交给它,回调拿到 status 200、正文 “hello from myproto: some/resource”;同时把 'ftp' 设成 None,ftp://example.com/x 的请求 errback 收到 NotSupported: Unsupported URL scheme 'ftp': no handler available for that scheme。", t=tl(S(3)), mark=lidx(S(3), 'handler 被调用', 'ftp://'), done=lidx(S(3), "'who': 'callback'"), kv=KV([['BaseDownloadHandler', '实现 async download_request → Response'], ['注册', 'DOWNLOAD_HANDLERS = {"协议": 类}'], ['值为 None', '禁用该协议,NotSupported']], ['BaseDownloadHandler'])),
    step("把 http/https 换成 AiohttpDownloadHandler(仍在默认的 asyncio reactor 下):日志有 WARNING “AiohttpDownloadHandler is experimental …”;48 个各 0.2 s 的请求、每域名并发 4:默认的 HTTP11 处理器服务器并发峰值 48(总耗时 0.27 s,每域名限制没生效),aiohttp 处理器峰值 4、总耗时 2.52 s(≈ 48 × 0.2 ÷ 4)——aiohttp 连接器自带 limit_per_host,每域名限制生效了。response.ip_address、protocol=HTTP/1.1 两个处理器一致。aiohttp 处理器的限制:meta bindaddress 被忽略并 ERROR “The 'bindaddress' request meta key is not supported by AiohttpDownloadHandler and will be ignored.”;meta proxy 指向不通的代理时 errback 收到 DownloadConnectionRefusedError(消息 “Cannot connect to host 127.0.0.1:1 …”,说明请求确实去连了代理)。", t=tl(S(4)), mark=lidx(S(4), 'AiohttpDownloadHandler:48', 'bindaddress', 'proxy="http'), done=lidx(S(4), '默认 HTTP11DownloadHandler'), b=bars([['HTTP11 处理器 峰值', 48, '48 并发'], ['Aiohttp 处理器 峰值', 4, '4 并发']], 48, mark=[1], done=[0]), kv=KV([['默认 HTTP11', '每域名并发 4 没生效:峰值 48'], ['Aiohttp 处理器', '峰值 4,耗时 2.52 s'], ['bindaddress', 'aiohttp 处理器忽略并 ERROR'], ['状态', '实验性,有警告']], ['Aiohttp 处理器'])),
]
A = mkarts('s44', 44, 'Scrapy,下载处理器,DOWNLOAD_HANDLERS,file,data URI,aiohttp,真实验证,动画演示',
    '实测 Scrapy 2.19 的下载处理器:协议到处理器的映射;file:// 与 data: 返回的响应类;自己写 BaseDownloadHandler 注册新协议、把 ftp 设成 None 禁用;换成实验性的 AiohttpDownloadHandler 后每域名并发限制真的生效(峰值 4 对 48),但 bindaddress 被忽略。',
    '请求最终是谁发出去的?file://、data: 是怎么处理的?能不能自己加一个协议?把 HTTP 处理器换成 aiohttp 会有什么不同?这篇从 DOWNLOAD_HANDLERS 讲起,把几种处理器的行为实测一遍。',
    [('6 个', 'DOWNLOAD_HANDLERS_BASE 里的协议:data、file、ftp、http、https、s3'), ('48 → 4', '换成 AiohttpDownloadHandler 后,每域名并发 4 的服务器峰值(默认处理器是 48)'), ('None', '把某协议的处理器设成它就禁用该协议')],
    [('协议映射', '<p>每个 URL 协议对应一个处理器类;<code>DOWNLOAD_HANDLERS</code> 覆盖或追加基础映射,值为 <code>None</code> 禁用。</p>'),
     ('本地协议', '<p><code>file://</code> 直接读本地文件,<code>data:</code> 解析 URI,都不走网络和下载槽;响应类按扩展名或 MIME 判定,file 响应没有头。</p>'),
     ('自定义协议', '<p>继承 <code>BaseDownloadHandler</code> 并实现 <code>async download_request(request)</code> 返回 <code>Response</code> 即可注册新协议。</p>'),
     ('换 HTTP 处理器', '<p><code>AiohttpDownloadHandler</code>(实验性)自带连接数限制,所以每域名并发限制生效;不支持 <code>bindaddress</code>,会记 ERROR 并忽略。</p>')],
    steps,
    [ENV_Y + '。file:// 与 data: 用临时文件和内联 URI;自定义处理器是一个返回 TextResponse 的最小实现;处理器对比用本机服务器每个请求延迟 0.2 s,统计服务器并发峰值',
     '没有验证:_httpx 处理器(需要另装 httpx / httpcore2,没有装);FTP、S3 处理器(没有可用的服务器);HTTP/2 处理器(见下一篇);处理器之间的响应头、cookie、压缩、重定向行为差异的全面对比(只比了并发限制、ip_address、protocol);处理器的 lazy 属性与 close() 的行为'],
    '下载处理器')
